# Recursively search for session-artifacts
def find_dir(start_path, target_name):
    for item in start_path.rglob("*"):
        if item.name == target_name and item.is_dir():
            return item
    return None

session_artifacts = find_dir(workspace, "session-artifacts")
if session_artifacts:
    print(f"Found: {session_artifacts}")
    items = list(session_artifacts.iterdir()[:50])
    for item in items[:10]:
        print(f"  {item.name} ({'isdir' if item.is_dir() else 'file'})")

    # Look for kernel state
    for item in items[:50]:
        if 'kernel-state' in str(item).lower():
            print(f"\n\nKernel state: {item}")
            try:
                with open(item) as fp:
                    data = json.load(fp)
                keys_with_demo = [k for k in data.keys() if 'demo' in k.lower()]
                if keys_with_demo:
                    print(f"  Demo-related keys: {keys_with_demo[:10]}")
